# -*- coding: utf-8 -*-
# Класс «коэффициент уехал в знаменатель»: −(1/3)x записано как \dfrac{-1}{3x} (линейная функция превратилась в гиперболу). Прочтение подтверждено ключом (и OCR для № 323). 26.09
P = {}
W = "в условии коэффициент при переменной записан как дробь с переменной в знаменателе ({a} вместо {b}), из-за чего линейная функция читалась как гипербола; ключ соответствует линейному прочтению"
def E(t, why, **kw): P[t] = dict(why=why, src="сверка с ключом (+ OCR учебника для Макарычев 7 № 323), 26.09", **kw)
E("G7_TB_16_323.2", W.format(a="−1/(3x)", b="−(1/3)x") + " (сверено с учебником № 323 б)); бессодержательные варианты «Неверно», «Нельзя однозначно ответить» заменены типичными ошибками",
  q=r"В какой точке пересекает ось $x$ график функции, заданной формулой $y = -\dfrac{1}{3}x + 8$?",
  dnew={0: (r"$(-24; 0)$", "Ученик ошибся в знаке при решении уравнения −x/3 + 8 = 0."), 1: (r"$(0; 8)$", "Ученик нашёл точку пересечения с осью y, а не с осью x.")})
E("G7_TB_15_312.1", W.format(a="−1/(3x)", b="−(1/3)x") + ": при x = −6 значение 2", q=r"Постройте график функции, заданной формулой $y=-\dfrac{1}{3}x$. Найдите по графику значение $y$, соответствующее $x$, равному $-6$; $-3$; $6$")
E("G7_TB_15_312.2", W.format(a="−1/(3x)", b="−(1/3)x") + ": y = −2 при x = 6", q=r"Постройте график функции, заданной формулой $y=-\dfrac{1}{3}x$. Найдите по графику значение $x$, которому соответствует $y$, равное $-2$; $1$; $2$")
E("G7_ALG_32_1.3", W.format(a="−1/(4x)", b="−(1/4)x") + ": y(−3) = 0,75, y(0) = 0 (у гиперболы x = 0 не входит в область определения)",
  q=r"Заполните таблицу для функции $y = kx$: для $x = -3, -2, -1, 0, 1, 2, 3$ найдите значения функции $y = -\dfrac{1}{4}x$.")
E("G7_ALG_32_10.2", W.format(a="−8/(3x)", b="−(8/3)x") + ": y(−3) = 12, y(0) = 4", q=r"Используя данную функцию, заполните таблицу: $y = -\dfrac{8}{3}x + 4$")
E("G7_ALG_33_2.1", W.format(a="1/(3x)", b="(1/3)x") + "; ключ был неполным (только x = 3), а требуется пара x и y: 4x − 10 = x/3 + 1 ⇒ x = 3, y = 2",
  q=r"Графически найдите значения $x$ и $y$: $y=4x-10$, $y=\dfrac{1}{3}x+1$.", k=r"$(3; 2)$")
E("G7_ALG_33_2.4", W.format(a="−4/(9x), −7/(5x)", b="−(4/9)x, −(7/5)x") + ": прямые пересекаются в (0; −3)",
  q=r"Графически найдите значения $x$ и $y$: $y=-\dfrac{4}{9}x-3$, $y=-\dfrac{7}{5}x-3$.")
E("G7_ALG_33_11", W.format(a="−1/(3x), 1/(3x)", b="−(1/3)x, (1/3)x") + "; ответ 1, 4 не меняется",
  q=r"Найдите прямые, параллельные прямой $y=3x+5$: 1) $y=3x-5$; 2) $y=9x-5$; 3) $y=-3x-5$; 4) $y=3x-15$; 5) $y=-\dfrac{1}{3}x-\dfrac{1}{5}$; 6) $y=\dfrac{1}{3}x+5$.")
E("G7_ALG_33_9", W.format(a="1/(3x), −5/(2x), 1/(2x)", b="(1/3)x, −(5/2)x, (1/2)x") + "; кроме того, номера пунктов склеились с числами («26)» = «2; 6)», «27)» = «2; 7)», «58)» = «5; 8)»); восстановлено по ключу: все четыре пары ему удовлетворяют",
  q=r"По графику найдите пару $x$ и $y$, которая является решением системы уравнений, и проверьте результат: 5) $-x + 2y = -6$, $3x + 2y = 2$; 6) $-2x + 2y = -6$, $x + y = 2$; 7) $y = -2x + 2$, $y = \dfrac{1}{3}x - 5$; 8) $y = -\dfrac{5}{2}x - 10$, $y = \dfrac{1}{2}x + 4$.")
E("G8_TB_30_690", W.format(a="1/(4y)", b="(1/4)y") + " — в условии и ключе (в неверных вариантах уже было (1/4)y)",
  qrep=(r"\dfrac{1}{4y}-4x=0", r"\dfrac{1}{4}y-4x=0"), k=r"1) $x+y=5$, $\dfrac{1}{4}y-4x=0$, $0{,}6x-3=-1{,}2$; 2) $6y+3x=10$, $2x+4y=9$, $0{,}5y+0{,}25x=4{,}8$; 3) $2x+4y=10$, $15-3x=6y$")
E("G6_TB_13_569.2", W.format(a="3/(8y), 1/(4y)", b="(3/8)y, (1/4)y") + " (Виленкин 6 № 569 б)): 3/8·y + y − 1/4·y = 9/8·y; при y = 2 2/3 — 3, при y = 4/9 — 1/2",
  q=r"Упростите и найдите значение выражения $\dfrac{3}{8}y+y-\dfrac{1}{4}y$ при $y=2\dfrac{2}{3}$; $\dfrac{4}{9}$.", k=r"$\dfrac{9}{8}y$; $3$; $\dfrac{1}{2}$")
